const screen=document.querySelector('#screen');
const examples=[{id:1,name:'行驶中异常断电反馈',source:'企微社群',topic:'车辆安全',status:'优先核验',text:'【虚构示例】今天通勤时突然断电，重新开机后恢复，想确认需要检查什么。',reason:'包含具体使用场景和异常现象，应优先人工核验；不能据此确定故障原因。'},{id:2,name:'充电反复中断',source:'抖音评论',topic:'充电体验',status:'待核验',text:'【虚构示例】充电断断续续，换插座还是一样。',reason:'独立评论，无法获得上下文。仅识别充电异常表述，车型、原因与事件真实性尚未确认。'},{id:3,name:'维修进度沟通不及时',source:'小红书',topic:'售后服务',status:'待核验',text:'【虚构示例】送修后没有明确进度，希望能告知预计完成时间。',reason:'主要诉求是维修进度与沟通，不能直接归因为安全故障。'},{id:4,name:'同类续航疑问',source:'民间微信群',topic:'续航体验',status:'持续观察',text:'【虚构示例】最近通勤耗电快了，有没有相同使用情况？',reason:'缺少温度、负载和骑行习惯信息，保留为体验线索，不推断电池质量问题。'}];
let topicIndex=0;const confirmed=new Set();
const topics=[{name:'充电体验',id:2,records:12,channels:3},{name:'车辆安全',id:1,records:6,channels:2},{name:'售后服务',id:3,records:9,channels:2},{name:'续航体验',id:4,records:18,channels:3}];
function spark(){return `<svg class="trend" viewBox="0 0 620 190" role="img" aria-label="社群与公域的虚构线索趋势"><g stroke="#e4e9ee"><path d="M20 30H600M20 80H600M20 130H600"/></g><path d="M20 121L58 105L96 116L134 89L172 102L210 75L248 92L286 59L324 32L362 60L400 53L438 87L476 73L514 109L552 101L600 88" fill="none" stroke="#4b9cec" stroke-width="2.5"/><path d="M20 143L58 130L96 144L134 112L172 123L210 100L248 109L286 81L324 71L362 95L400 87L438 119L476 107L514 133L552 122L600 136" fill="none" stroke="#e8b94e" stroke-width="2.5"/><text x="20" y="177">08.01</text><text x="162" y="177">08.08</text><text x="306" y="177">08.15</text><text x="448" y="177">08.22</text><text x="565" y="177">08.31</text></svg>`}
const legend='<div class="legend"><span><i></i>社群线索</span><span><i class="yellow"></i>公域线索</span></div>';
const topbar=()=>`<div class="topbar"><div class="brand"><i>N</i>ninebot.</div><div class="topnav"><a class="chosen" href="#blue">总览</a><a href="#silver">风险核验</a><a href="#orange">问题关联</a></div><span class="period">2026.08.01 — 08.31 / 示例</span></div>`;
function blue(){return `<section class="app-shell">${topbar()}<div class="body-pad"><div class="blue-hero"><div><div class="overline">USER VOICE / AUGUST</div><h1>用户声音<br>全景观察</h1><p class="small">从渠道反馈，到值得关注的问题。</p><button class="button" data-open="1">查看优先核验事件</button></div><div class="channel-flow" aria-label="社群和公域输入汇总为问题线索"><div class="flow-column"><div class="flow-node">企微社群</div><div class="flow-node">民间微信群</div></div><div class="flow-line"></div><div class="flow-hub">问题线索</div><div class="flow-line"></div><div class="flow-column"><div class="flow-node">公域 VOC</div><div class="flow-node">四个平台</div></div></div><div class="feature"><div class="small">示例分析内容</div><div class="counter">8,640</div><p class="small">历史回放 / 非实时监控</p><div style="margin-top:28px" class="small">本月观察主题</div><p style="font-size:25px;margin-top:6px">12 <span style="font-size:13px">个</span></p></div></div><div class="metric-grid">${[['待核验事件',4-confirmed.size,'模拟确认后更新',70],['优先核验',confirmed.has(1)?0:1,'安全相关表述',25],['示例覆盖渠道',6,'社群 + 公域平台',100],['待观察主题',12,'非已确认故障',60]].map(([s,n,note,w])=>`<section class="panel"><div class="small">${s}</div><div class="number">${n}<span>${s.includes('事件')?'条':''}</span></div><div class="small">${note}</div><div class="meter"><i style="width:${w}%"></i></div></section>`).join('')}</div><div class="lower-grid"><section class="panel"><div class="head"><h2>问题线索变化</h2><span class="badge">虚构趋势</span></div>${legend}${spark()}<p class="small">社群与 VOC 筛选口径不同，不直接比较负面率。</p></section><section class="panel"><div class="head"><h2>重点事件</h2><a href="#silver" class="small">全部核验 ›</a></div>${examples.slice(0,3).map(c=>`<button class="list-row" data-open="${c.id}"><span class="priority">${confirmed.has(c.id)?'已确认':'待核验'}</span><span><strong>${c.name}</strong><span class="small">${c.source} / ${c.topic}</span></span><span class="arrow">›</span></button>`).join('')}</section></div></div><footer class="foot">01 / 参考图 1 的蓝黄配色、主视觉带与紧凑图表布局。采用系统字体，不依赖外部字体或图片服务。</footer></section>`}
function silver(){return `<section class="app-shell silver-shell"><aside class="rail"><div class="brand">N / ninebot.</div><a href="#blue">态势总览</a><a class="active" href="#silver">风险核验</a><a href="#orange">问题关联</a><div class="rail-note">设计评审模式<br>仅虚构数据<br>不发送通知</div></aside><div class="silver-main"><div class="breadcrumbs">舆情工作空间 / 八月历史回放 / 风险核验</div><div class="silver-title"><div><h1>风险核验</h1><p class="small" style="margin-top:12px">Review workspace / 先证据，再判断</p></div><span class="badge">2026 年 8 月 · 示例</span></div><div class="silver-hero"><div><div class="small">待核验事件</div><div class="number">${4-confirmed.size}<span>/ 4</span></div><div class="small">当前页面的演示状态</div></div><div><div class="small">已确认（模拟）</div><div class="number">${confirmed.size}<span>条</span></div><div class="small">刷新后恢复初始状态</div></div><p class="explanation"><mark>关注证据完整性</mark><br><br>独立评论无上下文。缺少的信息保持未知，不由模型补造。</p></div><section class="panel"><div class="head"><h2>事件队列</h2><button class="button" id="reset-ref">重置演示</button></div><div class="tools"><input id="ref-search" placeholder="搜索事件或问题类型" aria-label="搜索事件"><select id="ref-source" aria-label="筛选来源"><option>全部来源</option>${examples.map(c=>`<option>${c.source}</option>`).join('')}</select></div><div id="ref-table"></div></section><div class="silver-bottom"><section class="panel"><div class="head"><h2>线索趋势</h2><span class="small">虚构 / 非实测</span></div>${legend}${spark()}</section><section class="panel"><h2>核验流程</h2><div class="path"><span>输入筛选</span>›<span>证据分析</span>›<span>人工核验</span>›<span>模拟预警</span></div><p class="small" style="margin-top:25px">VOC 保留原始研判结果，本系统单独记录风险结论；同类问题不等于同一事件。</p></section></div><footer class="foot">02 / 参考图 2 的银灰层次、炭黑文字与少量荧光绿。信息密度为实际阅读做了放大。</footer></div></section>`}
function relation(t){return `<svg class="relation-svg" viewBox="0 0 600 440" role="img" aria-label="${t.name}的虚构关联示意，不表示实际传播路径"><g stroke="#bac1b9" stroke-width="1.4" fill="none"><path d="M95 105L300 210L490 80M300 210L100 325M300 210L486 330M300 210L335 390"/><circle cx="300" cy="210" r="125" stroke-dasharray="3 9"/><circle cx="300" cy="210" r="170" stroke="#d3d7d1"/></g><g fill="#f7f8f3" stroke="#bbc4b8"><rect x="28" y="72" width="135" height="68" rx="4"/><rect x="420" y="48" width="145" height="68" rx="4"/><rect x="28" y="296" width="145" height="68" rx="4"/><rect x="416" y="298" width="145" height="68" rx="4"/></g><g text-anchor="middle"><text x="95" y="111">公域评论</text><text x="492" y="87">社群反馈</text><text x="100" y="335">使用场景</text><text x="490" y="337">待核验信息</text></g><circle cx="300" cy="210" r="66" fill="#ff793f"/><text class="center-text" x="300" y="215" text-anchor="middle">${t.name}</text><circle cx="335" cy="390" r="8" fill="#fff4a0" stroke="#b4b9a5"/></svg>`}
function orange(){const t=topics[topicIndex];return `<section class="app-shell orange-shell">${topbar()}<div class="orange-layout"><aside class="orange-left"><div class="overline small">ISSUE EXPLORER</div><h1>问题关联<br>观察视图</h1><p class="small">选择主题，查看示例线索。</p><div class="topics">${topics.map((s,i)=>`<button data-topic="${i}" class="topic-button ${i===topicIndex?'selected':''}" aria-pressed="${i===topicIndex}">${s.name}</button>`).join('')}</div><div class="mini-stat"><b>2026.08</b><p>历史回放 / 虚构主题</p></div></aside><section class="relation-center"><div class="map-label"><span>关系视图 / 非地理地图</span><span>示意 · 非算法结果</span></div>${relation(t)}<div class="relation-note">连线表示此样品中的信息组织关系，不表示传播方向、真实因果或已确认的跨渠道事件。独立评论不拼造上下文。</div></section><aside class="orange-right"><section class="focus-summary"><div class="overline small">CURRENT FOCUS</div><h2>${t.name}<br>08 / ${String(topicIndex+1).padStart(2,'0')}</h2><span class="badge">${confirmed.has(t.id)?'已确认（模拟）':'待人工核验'}</span><div class="numbers"><div><b>${t.channels}</b><span class="small">示例渠道</span></div><div><b>${t.records}</b><span class="small">示例线索</span></div></div></section><section class="focus-card"><div class="overline">EVIDENCE FIRST</div><div class="focus-num">${String(topicIndex+1).padStart(2,'0')}</div><p>关联只是线索，<br>结论需要证据。</p><p class="small" style="margin-top:24px">打开示例，查看原文、信息缺口与人工核验建议。</p><button class="button" data-open="${t.id}">查看证据与核验 ›</button></section></aside></div><footer class="foot">03 / 参考图 3 的灰白大视图、两侧面板与橙色重点区。用问题关系代替地理地图。</footer></section>`}
function table(){const q=document.querySelector('#ref-search').value.trim();const s=document.querySelector('#ref-source').value;const data=examples.filter(c=>(s==='全部来源'||c.source===s)&&(c.name.includes(q)||c.topic.includes(q)));document.querySelector('#ref-table').innerHTML=data.length?`<div class="table-scroll"><table><thead><tr><th>事件与主题</th><th>来源</th><th>状态</th><th>操作</th></tr></thead><tbody>${data.map(c=>`<tr><td>${c.name}<small>${c.topic} / 虚构案例</small></td><td>${c.source}</td><td><span class="status ${c.id===1?'hot':''}">${confirmed.has(c.id)?'已确认（模拟）':c.status}</span></td><td><button data-open="${c.id}">核验证据</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">没有匹配事件，请调整搜索或来源。</p>'}
function render(){let mode=location.hash.slice(1)||'blue';if(!['blue','silver','orange'].includes(mode))mode='blue';document.querySelectorAll('[data-mode]').forEach(a=>{if(a.dataset.mode===mode)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});screen.innerHTML=mode==='silver'?silver():mode==='orange'?orange():blue();if(mode==='silver'){table();document.querySelector('#ref-search').oninput=table;document.querySelector('#ref-source').onchange=table;document.querySelector('#reset-ref').onclick=()=>{confirmed.clear();render()}}}
function openEvidence(id){const c=examples.find(x=>x.id===id);const dialog=document.querySelector('#evidence');document.querySelector('#evidence-content').innerHTML=`<div class="overline small">SYNTHETIC EXAMPLE / 0${id}</div><h2>${c.name}</h2><span class="badge">${c.source} / ${c.topic}</span><h3>原文 · 虚构示例</h3><blockquote>${c.text}</blockquote><h3>核验提示</h3><p>${c.reason}</p><p class="small" style="margin-top:20px">未接入真实数据。这里的解释是设计文案，不是模型实际运行结果。</p><div class="dialog-actions"><button class="button" id="ref-confirm">${confirmed.has(id)?'已确认（模拟）':'模拟确认'}</button><button class="button" id="ref-return">返回</button></div><div id="ref-confirm-note" role="status"></div>`;document.querySelector('#ref-confirm').onclick=()=>{confirmed.add(id);document.querySelector('#ref-confirm').textContent='已确认（模拟）';document.querySelector('#ref-confirm-note').innerHTML='<p class="success">已记录本页演示状态；没有发送通知，刷新后重置。</p>';render()};document.querySelector('#ref-return').onclick=()=>dialog.close();dialog.showModal()}
document.addEventListener('click',e=>{const event=e.target.closest('[data-open]');if(event)openEvidence(Number(event.dataset.open));const topic=e.target.closest('[data-topic]');if(topic){topicIndex=Number(topic.dataset.topic);render()}});document.querySelector('.dismiss').onclick=()=>document.querySelector('#evidence').close();window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
